mapper.select:
select moi.order_item_id as orderItemId, moi.order_id as orderId, mo.order_no as orderNo, moi.product_id as productId, moi.sku_id as skuId, moi.product_name as productName, moi.sku_name as skuName, moi.sale_price as salePrice, moi.quantity as quantity, moi.total_amount as totalAmount, moi.refunded_quantity as refundedQuantity, moi.refunded_amount as refundedAmount, moi.del_flag as delFlag, moi.create_time as createTime, moi.update_time as updateTime from mall_order_item moi left join mall_order mo on moi.order_id = mo.order_id and mo.del_flag = 0 where moi.del_flag = 0
and moi.order_id = #{orderId}
and mo.order_no like concat('%', #{orderNo}, '%')
and moi.product_id = #{productId}
and moi.sku_id = #{skuId}
and moi.product_name like concat('%', #{productName}, '%')
and moi.sku_name like concat('%', #{skuName}, '%')
order by moi.order_item_id desc

select moi.order_item_id as orderItemId, moi.order_id as orderId, moi.product_id as productId, moi.sku_id as skuId, moi.product_name as productName, moi.sku_name as skuName, moi.sale_price as salePrice, moi.quantity as quantity, moi.total_amount as totalAmount, moi.refunded_quantity as refundedQuantity, moi.refunded_amount as refundedAmount, moi.del_flag as delFlag, moi.create_time as createTime, moi.update_time as updateTime from mall_order_item moi where moi.del_flag = 0
and moi.order_id = #{orderId}
and moi.product_id = #{productId}
and moi.sku_id = #{skuId}
and moi.product_name like concat('%', #{productName}, '%')
and moi.sku_name like concat('%', #{skuName}, '%')
order by moi.order_item_id desc

